Given a number x, determine whether the given number is Armstrong's number or not. A positive integer  of n digits is called an Armstrong number of order n (order is the number of digits) ifabcd... = pow(a,n) + pow(b,n) + pow(c,n) + pow(d,n) + .... Here a, b, c and d are digits of input number abcd.....ExamplesInput: n = 153Output: trueExplanation: 153 is an Armstrong number, 1*1*1 + 5*5*5 + 3*3*3 = 153Input: n = 9474Output: trueExplanation: 94 + 44 + 74 + 44 = 6561 + 256 + 2401 + 256 = 9474Input: n = 123Output: falseExplanation: 1³ + 2³ + 3³ = 1 + 8 + 27 = 36Try It YourselfTable of Content[Approach 1] Naive Approach[Approach 2] Using Numeric Strings[Approach 1] Naive ApproachThe idea is to first count the number of digits (or find the order). Let the number of digits be n. For every digit r in input number x, compute rn. If the sum of all such values is equal to x, then return true, else false. 
            C++

    #include <iostream>
using namespace std;

// Function to calculate x raised 
// to the power y 
int power(int x, int y){
    if (y == 0)
        return 1;
    if (y % 2 == 0)
        return power(x, y / 2) * power(x, y / 2);
    return x * power(x, y / 2) * power(x, y / 2);
}


int order(int n){
    int t = 0;
    while (n) {
        t++;
        n = n / 10;
    }
    return t;
}

// Function to check whether the given 
// number is Armstrong number or not
bool armstrong(int n){

    // Calling order function
    int x = order(n);
    int temp = n, sum = 0;
    while (temp) {
        int r = temp % 10;
        sum += power(r, x);
        temp = temp / 10;
    }

    return (sum == n);
}

int main()
{
    int n = 153;
    if(armstrong(n)){
        cout << "true";
    }else{
        cout << "false";
    }
    return 0;
}


